"""Conversions between the application models and the "orders" table: what the service takes and returns."""

from __future__ import annotations

from app.application_models import OrderSummary
from app.dtos.order import OrderCreate, OrderRead


def order_summary_to_order_create(model: OrderSummary) -> OrderCreate:
    """An OrderSummary as the orders table takes it."""
    return OrderCreate(
        # TODO: customer_id: no field of the model gives it
        total_cents=round(model.total * 100),
        # TODO: note: Mapper's relation only goes the other way (label)
    )


def order_read_to_order_summary(row: OrderRead) -> OrderSummary:
    """A row of the orders table as an OrderSummary."""
    return OrderSummary(
        id=row.id,
        total=row.total_cents / 100,
        placedAt=row.placed_at,
        # TODO: label: DB2CRUD does not write this conversion ('#' + id + ' ' + note)
        label=None,
    )

