"""Repository of the "orders" table: reads and writes rows, and decides nothing."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any, Protocol

from sqlalchemy import func, select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.entities.order import Order
from app.errors import ConflictError
from app.paging import Page


class OrderRepository(Protocol):
    """Where orders rows are kept. Services depend only on this interface."""

    def find_by_id(self, id: int) -> Order | None:
        """The row with this primary key, or None."""
        ...

    def list(self, offset: int = 0, limit: int = 50) -> Page[Order]:
        """At most `limit` rows from `offset`, by primary key, and how many there are."""
        ...

    def insert(self, entity: Order) -> Order:
        """Stores a new row; the values the database fills are read back."""
        ...

    def update(self, entity: Order) -> Order:
        """Stores the changes made to a row read from this repository."""
        ...

    def delete(self, entity: Order) -> None:
        """Removes a row read from this repository."""
        ...


class SqlOrderRepository:
    """Keeps orders rows in the database, through a Session. It never commits: the transaction belongs to whoever holds the session."""

    def __init__(self, session: Session) -> None:
        self._session = session

    def find_by_id(self, id: int) -> Order | None:
        """The row with this primary key, or None."""
        return (self._session.scalars(select(Order).where(Order.id == id))).first()

    def list(self, offset: int = 0, limit: int = 50) -> Page[Order]:
        """At most `limit` rows from `offset`, by primary key, and how many there are."""
        query = select(Order)
        total = self._session.scalar(select(func.count()).select_from(query.subquery())) or 0
        rows = (self._session.scalars(query.order_by(Order.id).offset(offset).limit(limit))).all()
        return Page(items=list(rows), total=total, offset=offset, limit=limit)

    def insert(self, entity: Order) -> Order:
        """Stores a new row; the values the database fills are read back."""
        self._session.add(entity)
        try:
            self._session.flush()
        except IntegrityError as error:
            self._session.rollback()
            raise ConflictError("Order", "the database refused the change: " + str(error.orig)) from error
        self._session.refresh(entity)
        return entity

    def update(self, entity: Order) -> Order:
        """Stores the changes made to a row read from this repository."""
        self._session.add(entity)
        try:
            self._session.flush()
        except IntegrityError as error:
            self._session.rollback()
            raise ConflictError("Order", "the database refused the change: " + str(error.orig)) from error
        self._session.refresh(entity)
        return entity

    def delete(self, entity: Order) -> None:
        """Removes a row read from this repository."""
        self._session.delete(entity)
        try:
            self._session.flush()
        except IntegrityError as error:
            self._session.rollback()
            raise ConflictError("Order", "the database refused the change: " + str(error.orig)) from error


class MemoryOrderRepository:
    """Keeps orders rows in memory, for tests and for trying the services without a database."""

    def __init__(self) -> None:
        self._rows: dict[tuple[Any, ...], Order] = {}
        self._next_id = 1

    @staticmethod
    def _key(row: Order) -> tuple[Any, ...]:
        return (row.id,)

    def find_by_id(self, id: int) -> Order | None:
        """The row with this primary key, or None."""
        return next((row for row in [row for row in sorted(self._rows.values(), key=self._key) if True] if row.id == id), None)

    def list(self, offset: int = 0, limit: int = 50) -> Page[Order]:
        """At most `limit` rows from `offset`, by primary key, and how many there are."""
        rows = [row for row in sorted(self._rows.values(), key=self._key) if True]
        return Page(items=rows[offset : offset + limit], total=len(rows), offset=offset, limit=limit)

    def insert(self, entity: Order) -> Order:
        """Stores a new row; the values the database fills are read back."""
        if entity.id is None:
            entity.id = self._next_id
            self._next_id += 1
        if entity.placed_at is None:
            entity.placed_at = datetime.now(UTC)
        self._rows[(entity.id,)] = entity
        return entity

    def update(self, entity: Order) -> Order:
        """Stores the changes made to a row read from this repository."""
        self._rows[(entity.id,)] = entity
        return entity

    def delete(self, entity: Order) -> None:
        """Removes a row read from this repository."""
        self._rows.pop((entity.id,), None)

