"""Operations on orders: what each one checks before it writes."""

from typing import Any

from app.dtos.order import OrderCreate, OrderRead, OrderUpdate
from app.entities.order import Order
from app.errors import FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"customer_id", "total_cents", "note"})


class OrderService:
    """Operations on orders. Each write runs in its own transaction."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    def _validate_all(self, values: dict[str, Any], current: Order | None) -> None:
        """Checks the values against the rules of the "orders" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Order"))
        if not creating:
            for name in values.keys() & {"id", "placed_at"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("customer_id")
        if value is None:
            if creating or "customer_id" in values:
                errors.append(FieldError("customer_id", "is required"))
        value = values.get("total_cents")
        if value is None:
            if creating or "total_cents" in values:
                errors.append(FieldError("total_cents", "is required"))
        if errors:
            raise ValidationFailedError("Order", errors)

    def _check(self, values: dict[str, Any], current: Order | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)

    def _find(self, id: int) -> Order:
        """The Order with this key; NotFoundError when there is none."""
        entity = self._uow.orders.find_by_id(id)
        if entity is None:
            raise NotFoundError("Order", id)
        return entity

    @staticmethod
    def _read(entity: Order) -> OrderRead:
        """The Order as services return it."""
        return OrderRead.model_validate(entity)

    def create_order(self, data: OrderCreate) -> OrderRead:
        """Stores a new Order after checking it."""
        values = data.model_dump(exclude_unset=True)
        with self._uow.transaction():
            self._check(values, None)
            created = self._uow.orders.insert(Order(**values))
            return self._read(created)

    def get_order(self, id: int) -> OrderRead:
        """The Order with this key; NotFoundError when there is none."""
        return self._read(self._find(id))

    def list_orders(self, offset: int = 0, limit: int = 50) -> Page[OrderRead]:
        """A page of orders, by primary key."""
        page = self._uow.orders.list(offset, limit)
        return Page(items=[self._read(entity) for entity in page.items], total=page.total, offset=page.offset, limit=page.limit)

    def update_order(self, id: int, data: OrderUpdate) -> OrderRead:
        """Changes the given values of a Order."""
        values = data.model_dump(exclude_unset=True)
        with self._uow.transaction():
            current = self._find(id)
            self._check(values, current)
            for name, value in values.items():
                setattr(current, name, value)
            updated = self._uow.orders.update(current)
            return self._read(updated)

    def delete_order(self, id: int) -> None:
        """Deletes a Order."""
        with self._uow.transaction():
            current = self._find(id)
            self._uow.orders.delete(current)

